#!/bin/bash
set -e

# Fix: duplicate Doctor queue tokens from the Optometry Complete
# button. Root cause was two-fold, both now fixed:
# 1. Client: the button re-enabled itself ~1.2s before actually
#    navigating away, leaving a window where a second click re-ran
#    completion. Now stays disabled through the navigation delay.
# 2. Database (optometry_complete RPC, already applied live to both
#    production and training): made idempotent -- a second call on
#    an already-completed entry just returns it, instead of issuing
#    another Doctor token. This is the real defense-in-depth fix,
#    since it protects against ANY double-trigger, not just this
#    specific click-timing scenario.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/optometry/[id]"
echo "" | base64 -d > "app/(main)/optometry/[id]/optometry-workspace.js"
echo "Wrote app/(main)/optometry/[id]/optometry-workspace.js"

git add "app/(main)/optometry/[id]/optometry-workspace.js"
git commit -m "Fix duplicate Doctor queue token: keep Complete button disabled through navigation delay"
git push

echo "Done."
